    // r = 0: no move -> identity
    // r = 1: apply swap(0,1)
    // r = 2: apply swap(0,1) then swap(1,2)
    const MAP: [[i8; 3]; 3] = [
        [0, 1, 2], // r = 0
        [1, 0, 2], // r = 1
        [1, 2, 0], // r = 2
    ];

